pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Deploy with 0 tokens, but we need owner to have balance to call burn
        // First, let owner mint some tokens to itself
        vm.prank(address(c.owner())); // The owner after deployment is the test contract (this) because setUp runs as msg.sender
        c.mintToken(address(this), 1000);

        // Now call burn as owner - only the buggy version will change owner during burn
        vm.prank(address(this)); // This is the owner
        c.burn(100);

        // Now try to transfer tokens as a non-owner - reference will succeed (owner unchanged), buggy will have owner=0 causing revert
        vm.prank(address(0x1234));
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", address(0x5678), 1));
        assertTrue(success);
    }
}

