pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        address attacker = address(0x456);
        vm.prank(attacker);
        bool ok;
        try c.burn(10) { ok = true; } catch { ok = false; }
        // Reference: attacker is not owner, so burn reverts (ok == false)
        // Bug: owned() incorrectly set owner to address(0x123) but never called here; so burn still reverts — wait, need to actually trigger the owned() function to make the difference observable.
        // Actually the mutant changes owned() but burn() uses onlyOwner modifier which checks msg.sender == owner. To make the difference observable, first call owned() (which in bug sets owner to 0x123, in reference sets to caller). Then attacker calls burn. In reference, owner is still deployer (since owned() onlyOwner already satisfied by deployer), attacker is not owner → revert. In bug, owned() sets owner to 0x123, attacker is not 0x123 → revert. Still same. Need different approach.
        // Let's instead: deployer calls owned() first to set owner to deployer (reference) or to 0x123 (bug). Then deployer calls burn, which succeeds. Now check owner value. In reference, owner unchanged (still deployer). In bug, owner changed to 0x123 after owned() call.
        // But the difference occurs only after owned() is called. So:
        // Step 1: deployer calls owned() — in reference sets owner to deployer (already), in bug sets to 0x123
        // Step 2: call burn from deployer (works)
        // Step 3: check c.owner() — reference = deployer, bug = 0x123
        address deployer = address(this);
        vm.prank(deployer);
        c.owned();
        vm.prank(deployer);
        c.burn(10);
        address expectedOwnerRef = deployer;
        address actualOwner = c.owner();
        assertTrue(actualOwner == expectedOwnerRef, "Owner should be deployer");
        // In bug, actualOwner == 0x123, which is not deployer → test fails
    }
}

