import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // The bug is in owned(): it sets owner to address(0x123) instead of msg.sender.
        // Call owned() from the deployer (which is the current owner).
        // In the reference, owned() sets owner to the deployer (no change).
        // In the buggy version, owned() sets owner to address(0x123).
        c.owned();
        // Now call burn(10) from the new owner (which may differ).
        // The reference still has original deployer as owner, so someone else calling burn will revert.
        // The buggy version has owner = address(0x123), so calling burn from address(0x123) will succeed.
        vm.prank(address(0x123));
        bool ok;
        try c.burn(10) { ok = true; } catch { ok = false; }
        // In the reference, ok is false (revert). In the buggy version, ok is true.
        assertTrue(ok);
    }
}

