        vm.deal(owner, 0);
        vm.prank(owner);
        c.owned();
        c.mintToken(owner, 100);
        c.mintToken(nonOwner, 10);

        vm.prank(nonOwner);
        bool ok;
        try c.burn(1) { ok = true; } catch { ok = false; }

        // Reference: ok == false, so balance unchanged => 10
