pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Deployed with initialSupply=0 => totalSupply=0, balanceOf[this]=0
        // Need owner to call mintToken. Owner is deployer (this contract).
        // First give some funds to target (say address(1)) via mintToken
        c.mintToken(address(1), 5);
        // Now totalSupply in reference: 0+5=5; in bug: 0-5 underflows (uint256 wraps to 2^256-5)
        // But to observe divergence via burn, we need balanceOf[msg.sender] >= _value
        // Currently msg.sender (this contract) has 0 balance. So mint to self: 10 tokens
        c.mintToken(address(this), 10);
        // Now reference: totalSupply=15, balanceOf[this]=10; bug: totalSupply underflowed then -5? Actually bug: first mint: totalSupply -= 5 => underflow, second mint: totalSupply -=10 => underflow again; balanceOf[this]=10 (both)
        // Now burn 10 from this contract
        bool success = false;
        try c.burn(10) {
            success = true;
        } catch {
            success = false;
        }
        // In reference, burn succeeds (balance 10 >=10, totalSupply 15-10=5).
        // In bug, burn may revert because totalSupply is underflowed huge? Actually burn does totalSupply -= _value, but totalSupply is uint256 huge from underflow, subtraction works, no revert. So both succeed.
        // But the divergence is totalSupply value after mintToken. Since we need a getter that differs: totalSupply is public getter.
        // After above, reference totalSupply = 5; bug totalSupply = (2^256-5-10) = 2^256-15 (due to underflows)
        // So assert that c.totalSupply() is the reference value.
        assertTrue(c.totalSupply() == 5);
    }
}

