pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Mint 100 tokens to owner (msg.sender is this contract)
        c.mintToken(address(this), 100);
        // Burn 50 tokens
        c.burn(50);
        // After burn, totalSupply should be 50, but buggy contract still has 100
        // Try to burn another 50 tokens: reference succeeds (totalSupply=50, balance=50)
        // Buggy contract: balance is 50, but totalSupply is 100, so burn should succeed too?
        // Actually the bug is missing totalSupply update in mintToken, so totalSupply remains initial 0.
        // Let's re-check: initial totalSupply = 0 * 10^0 = 0. Mint adds 100 to balance but totalSupply unchanged (=0). Burn reverts in reference because totalSupply < _value. But the mutant also reverts? No, buggy mintToken doesn't update totalSupply at all, so totalSupply stays 0. Burn require(balanceOf[msg.sender] >= _value) passes (balance=100), then balanceOf[msg.sender] -= _value; totalSupply -= _value; — this underflows totalSupply (0 - 50) reverting. So both revert? Wait, need different scenario.
        // Better approach: initial supply 100, no mint, then burn 60. Reference works, mutant works? The bug is in mintToken not updating totalSupply, so if we never mint, difference doesn't surface. Let's use initial supply 0, mint 100 to owner, then burn 60. Reference: after mint, totalSupply=100, balance=100. Burn 60 => totalSupply=40, balance=40. Mutant: after mint, totalSupply stays 0, balance=100. Burn 60: require(balanceOf[msg.sender] >= 60) true; balanceOf[msg.sender] -= 60 => 40; totalSupply -= 60 => 0-60 underflows, reverts. So reference succeeds, bug reverts.
        // But the assertion must be a fact that reference holds and bug breaks. For reference, burning works; for bug, it reverts. So we can assert that burn succeeds.
        // Actually let's re-do: set initial supply to 100 (constructor param first arg = 100). Then burn 60. Both succeed because totalSupply initially 100, correct. Bug is only in mintToken, so if we don't use mint, no difference. So we must use mint.
        // Constructor with initialSupply=0, then mint 100 to owner. Then burn 60. Reference: burn succeeds (totalSupply becomes 40). Mutant: burn reverts (totalSupply underflow). So we wrap burn in try/catch and assert that it succeeds.
        bool ok;
        try c.burn(60) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

